from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                # remove existing entry (whether expired or not, it's being overwritten)
                del cache[key]
            else:
                if len(cache) >= capacity:
                    # evict least recently used
                    cache.popitem(last=False)
            cache[key] = (value, t)
            cache.move_to_end(key)
        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                value, write_time = cache[key]
                if t >= write_time + ttl:
                    # expired
                    del cache[key]
                    results.append(-1)
                else:
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

    return results

